// === Tab: utils ===
// "hey clara what are all these funcitons you're not using?"
//
// well
// funny story
//
// i usually write these in a webpacked environment
// and then copy them over to OpenProcessing.
// so i have a list of utils i just like to have on hand, in one file
// i don't use all of them in every project 
// but sorting through which ones i use and which ones I don't is a pain
// so I just dump the whole file in here because i'm lazy

let isPaused = false;
let lapse = 0;
let frameStandard = 300;

const utils = {
	random_int: function(a, b) {
		  return Math.floor(random(a, b))
	},

	standardCanvas: function(override = false) {
		let smallerDimension = windowWidth < windowHeight ? windowWidth : windowHeight;
		smallerDimension -= 20; // for padding
		if (override) {
			smallerDimension = override;
		}

		return createCanvas(smallerDimension, smallerDimension);  
	},
	standardKeyPressed: function() {

		if(frameStandard > 30) {
			frameStandard = floor(frameRate());
		}

		if (key === "s") {		
			save()
		}
		if (key === "p") {
			frameRate(isPaused ? 30 : 0);
			isPaused = !isPaused;
			console.log(isPaused);
		} 
	},
	standardMouseReleasedFactory: function(resetFunction) {
		return function() {
			if (millis() - lapse > 200){
				clear();
				noiseSeed(random(1000));
				resetFunction();
				redraw();
			}
			lapse = millis();
			return false;  
		}
	},
	getMatrix: function(matrixVariation) {
		return [ // a very slightly messed up identity matrix 
			1 + random(-matrixVariation, matrixVariation), 
					random(-matrixVariation, matrixVariation), 
					random(-matrixVariation, matrixVariation),
			1 + random(-matrixVariation, matrixVariation), 
					random(-matrixVariation, matrixVariation),
					random(-matrixVariation, matrixVariation)
		];
	},
	relSize: function(pixelsIsh) {
		// this assumes square. my stuff is always square tho
		return width * (pixelsIsh / 1000);
	}
};


// === Tab: forms ===
// this would better be described as highlight arcs
function ring(i, t, aMatrix, aRandomNumber, rings, ringSize, colors, c) {
  c = random() < 0.3 ? random(colors) : c;
  c.setAlpha(map(1/rings, 0, 0.2, 0, 40));  

  stroke(c);
  noFill();

  applyMatrix(...aMatrix);
  strokeWeight(map(noise(i/rings, t), 0, 1, utils.relSize(1), utils.relSize(20)))

  let arcStart = noise(5, i/rings) * PI*2;
  let arcEnd = arcStart + noise(aRandomNumber + i)*PI*2;

  arc(width/2, height/2, ringSize, ringSize, arcStart, arcEnd);
}

// the main blurry shape
function fadeRing(i, s, rings, ringSize, colors, c) {
  let arcStart = noise(i, i / rings) * PI * 2;
  let arcEnd = arcStart - random(PI * 0.5);
  c = random() < 0.3 ? random(colors) : c;
  const r = map(noise(s+i), 0, 1, ringSize*0.75, ringSize*1.25);

  c.setAlpha(100/rings);

  stroke(c);
  strokeWeight(map(noise(i), 0, 1, utils.relSize(1), utils.relSize(200)))
  arc(width / 2, height / 2, r, r, arcStart, arcEnd);
}

// look, i know glitter lost, but, glitter
function flecks(i, t, ringSize, startAngle, c, colors) {
	const v = createVector(0, ringSize/2);
	// why didn't anyone tell me circle math is so much easier with vectors	
	v.rotate((noise(i/5) * 3*PI)+ startAngle);
  v.setMag(randomGaussian(ringSize/2, ringSize/10));
  v.add(width/2, height/2);

  c = random() > 0.3 ? c : random(colors);
  c.setAlpha(255 - (noise(i/5 + 1) * 255));

  fill(c);
  noStroke();
  const r = map(noise(i/5 + 0.1), 0, 1, utils.relSize(0.5), utils.relSize(25));

  push();
  rectMode(CENTER);
  translate(v.x, v.y);
  rotate(PI/4);

  if(noise(i*5, t*5) > 0.2) {
    ellipse(0, 0, r, r);
  }

  if(noise(i*5, t*5) > 0.65) {
    rect(0, 0, r*0.6, r*0.6);
  }
  pop();
}

// the "ridges" so to speak
function streaks(i, t, rings, ringSize, c, colors) {
  const streakOffset = 40;
  push();
  const ringIndex = floor(i/25);
  const offsetX = map(noise(ringIndex), 0, 1, -utils.relSize(streakOffset), utils.relSize(streakOffset));
  const offsetY = map(noise(1000 + ringIndex), 0, 1, -utils.relSize(streakOffset), utils.relSize(streakOffset));
  translate(offsetX, offsetY);
  c = random() < 0.1 ? random(colors) : c;
  c.setAlpha(100);  
  stroke(c);
  strokeWeight(map(noise(i/rings), 0, 1, utils.relSize(1), utils.relSize(4)))
  noFill();

  let arcStart = (noise(5, ringIndex)+ fract(t / ringIndex)/3) * PI*2;
  let arcEnd = arcStart + (PI * 2 * noise(20, ringIndex));

  const rs = ringSize * (noise(ringIndex) + 0.5);

  arc(width/2, height/2, randomGaussian(rs, utils.relSize(15)), randomGaussian(rs, utils.relSize(15)), arcStart, arcEnd);
  pop();
}


// the "grid lines" so to speak
function gridLines(i, s, ringSize, startAngle, c) {
  const v = createVector(0, ringSize/2);
  v.rotate((fract(i/130) * 2*PI) + floor(startAngle * s/3));
  v.setMag(map(noise(floor(i/12), s), 0, 1, ringSize/10, ringSize*0.85));

  const v2 = v.copy();
  v2.mult(random() > 0.1 ? 0.8 : 1.2);

  v.add(width/2, height/2);
  v2.add(width/2, height/2);

  c.setAlpha(255 - (noise(i/5 + 1) * 255));

  noFill();
  stroke(c);
  const w = map(noise(i/5 + 0.1), 0, 1, utils.relSize(0.5), utils.relSize(5));
  strokeWeight(w);
  line(v.x, v.y, v2.x, v2.y);
}

// === Tab: void ===
// By Clara Bower
// https://twitter.com/clarabellum

// Made for @sableRaph's weekly creative challenge on Twitch (#WCCChallenge)
// https://www.twitch.tv/sableraph

// This week: Void

let ringSize;
let mainColor;
let accentColor;
let streakColor;
let colors;

let rings = 100;
const minShift = -100;
const maxShift = 100;

let t; // sin time
let s; // cosine time 
let aRandomNumber; // for seeds
let aMatrix; // for weirdness

let startAngle = 0;

let shearAmount;

// despite what it sounds like, this is NOT for cross-browser support!
// https://twitter.com/clarabellum/status/1442906188576804865
const forceIE = false;

function setup() {  
  utils.standardCanvas();

  colors = [ // manually set to some colors i thought fit the vibe
    '#ff3311',
    '#1166ff',
    '#6633ff',
    '#ee6611',
    'rgb(50, 205, 209)',
    'rgb(120, 5, 205)',
    'rgb(211, 73, 39)',
    'rgb(254, 232, 20)'
  ];

  colors = colors.map((c) =>  color(c)); // get p5 versions

  reset();
	window.mouseReleased = utils.standardMouseReleasedFactory(reset);
	window.keyPressed = utils.standardKeyPressed;
  blendMode(ADD);
  strokeCap(SQUARE);  
}


function reset() {  
	// seeds and arbitrary stuff
  aRandomNumber = random(1000);
  aMatrix = utils.getMatrix(0.01);

	// stuff about shapes
	rings = random(50, 150);
	ringSize = utils.relSize(random(250, 600));
  startAngle = random(PI*2);

	shearAmount = random(-0.1, 0.1) * PI;

	// stuff about colors
  mainColor = random(colors);
  streakColor = random(colors);

  accentColor = mainColor;
  let _wG_1 = 0; while ((mainColor == accentColor) && ++_wG_1 < 20000) {
    accentColor = random(colors);
  }


  if(forceIE) {
    mainColor = colors[1];
    accentColor = colors[4];
    streakColor = colors[7];
    shearAmount = -Math.abs(shearAmount);
  }
}

function drawRing(i) {
  ring(i, t, aMatrix, aRandomNumber, rings, ringSize, colors, mainColor)
}
function drawFadedArc(i) {
  fadeRing(i, s, rings, ringSize, colors, mainColor) 
}
function drawFlecks(i) {
  flecks(i, t, ringSize, startAngle, accentColor, colors);
}
function drawLines(i) {
  gridLines(i, s, ringSize, startAngle, accentColor)
}
function drawStreaks(i) {
  streaks(i, t, rings, ringSize, streakColor, colors)
}


function draw() {
  clear();
  background(0);
  t = Math.sin(frameCount/80);
  s = Math.cos(frameCount/60);

	// setting the randomSeed to the same arbitrary number every draw
	// is what keeps the randomized elements in the same places
	// without having to save their location
	// you just have to make sure you call random() the same number of times
	randomSeed(aRandomNumber); 

  shearX(shearAmount);
	translate(width * (-shearAmount/2), 0); // wild that this works

	for (let index = 0; index < rings; index++) {
    push();

    translate(
      map(noise(index/rings, 1), 0, 1, utils.relSize(minShift), utils.relSize(maxShift)),
      map(noise(1, index/rings), 0, 1, utils.relSize(minShift), utils.relSize(maxShift))
    ); // jiggle the canvas around

    drawRing(index);
    drawFadedArc(index);
    drawFadedArc(index+0.5);

    drawFlecks(index);
    drawFlecks(index + 0.5);
    pop();
  }  

	// these I don't want jiggled
	// i want them twisted slightly in a consistent way.
	// hence, ...aMatrix. 
	applyMatrix(...aMatrix);

	// btw, i think in openProcessing you can just say applyMatrix(aMatrix)
	// but in my env you need to spread the matrix because webpack is stricter I guess

	for (let index = 0; index < rings; index++) {
    drawStreaks(index);
    drawLines(index);
  }

	// oh, and just to troll the OG generative artists
	// draw function returns void!
	return "void";
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
        BoxGeometry: class {}
    };
}
if (typeof window.Tone === 'undefined') {
    window.Tone = {
        Player: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Players: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Sampler: class { triggerAttackRelease() {} connect() {} toDestination() {} },
        Sequence: class { start() {} stop() {} },
        Transport: { start: function() {}, stop: function() {}, bpm: { value: 120 } }
    };
}
if (typeof window.createREGL === 'undefined') {
    window.createREGL = function() {
        const regl = function() {};
        regl.texture = function() { return { resize: function() {} }; };
        regl.buffer = function() { return { subdata: function() {} }; };
        regl.framebuffer = function() { return { use: function(cb) { cb(); } }; };
        return regl;
    };
}
if (typeof window.Voronoi === 'undefined') {
    window.Voronoi = class {
        compute() { return { cells: [], edges: [] }; }
    };
}
if (typeof window.qrcode === 'undefined') {
    window.qrcode = function(data) {
        return {
            createImgTag: function() { return ""; },
            createTableTag: function() { return ""; },
            createSvgTag: function() { return ""; }
        };
    };
    window.qrcode.stringToBytes = function(s) { return []; };
}
if (typeof window.PolyK === 'undefined') {
    window.PolyK = {
        Slice: function() { return []; },
        Triangulate: function() { return []; },
        getArea: function() { return 0; }
    };
}
if (typeof window.P5Capture === 'undefined') {
    window.P5Capture = {
        getInstance: function() {
            return { start: function() {}, stop: function() {}, setFormat: function() {} };
        },
        setDefaultOptions: function() {}
    };
}

// 1.9 免疫 OPC (OpenProcessing Controller) 與 WebGL 內部 setUniform 崩潰
if (typeof window.OPC === 'undefined') {
    window.OPC = {
        title: function() {},
        slider: function() {},
        button: function() {},
        toggle: function() {},
        color: function() {}
    };
}
if (typeof p5 !== 'undefined' && p5.Shader) {
    const origSetUniform = p5.Shader.prototype.setUniform;
    p5.Shader.prototype.setUniform = function(name, val) {
        if (!this) return this;
        try {
            return origSetUniform.call(this, name, val);
        } catch(e) {
            return this;
        }
    };
}

// 1.95 免疫某些特定遊戲模組對 parent / maeExportApis_ 或是唯讀屬性的寫入崩潰
try {
  if (typeof window.parent !== 'undefined') {
    if (!window.parent.maeExportApis_) {
      try {
        window.parent.maeExportApis_ = function() {};
      } catch(e) {}
    }
  }
} catch(e) {}

// 1.96 免疫 textmode 缺失以及 loadSVG / p5.SVG 插件型別拋錯
if (typeof textmode === 'undefined') { window.textmode = function() {}; }
if (typeof MAT === 'undefined') { window.MAT = []; }
if (typeof SIDES === 'undefined') { window.SIDES = 4; }
if (typeof GRIDBOX === 'undefined') { window.GRIDBOX = 10; }
if (typeof COLUMNS === 'undefined') { window.COLUMNS = 5; }
if (typeof tileSize === 'undefined') { window.tileSize = 30; }
if (typeof mouseTileX === 'undefined') { window.mouseTileX = 0; }
if (typeof p5 !== 'undefined') {
  if (!p5.prototype.loadSVG) {
    p5.prototype.loadSVG = function(path, success, failure) {
      if (success) success({});
      return {};
    };
  }
  // 免疫 window.VERSION 唯讀寫入錯誤
  try {
    Object.defineProperty(window, 'VERSION', {
      value: "p5-stub",
      writable: true,
      configurable: true
    });
  } catch(e) {}
}

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || path.startsWith('http') || (path.startsWith('data:') === false && path.indexOf('.') === -1)) {
            // 當發現是遠端 URL、相對路徑或格式無副檔名時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖與 CORS 錯誤
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };

    // 修正 img.loadPixels / img.resize 缺失與未非同步載入完成呼叫
    if (!p5.Image.prototype.loadPixels) { p5.Image.prototype.loadPixels = function() { return this; }; }
    if (!p5.Image.prototype.resize) { p5.Image.prototype.resize = function() { return this; }; }
    if (!p5.Image.prototype.get) { p5.Image.prototype.get = function() { return [0,0,0,255]; }; }
    if (!p5.Image.prototype.width) {
        Object.defineProperty(p5.Image.prototype, 'width', {
            get: function() { return this._width || 1280; },
            set: function(v) { this._width = v; }
        });
    }
    if (!p5.Image.prototype.height) {
        Object.defineProperty(p5.Image.prototype, 'height', {
            get: function() { return this._height || 720; },
            set: function(v) { this._height = v; }
        });
    }

    // 修正 p5.Graphics / p5.Renderer / Element.prototype.style
    if (p5.Graphics && p5.Graphics.prototype) {
        if (!p5.Graphics.prototype.loadPixels) { p5.Graphics.prototype.loadPixels = function() { return this; }; }
    }
}

// 2.2 修正 p5.Table / loadTable / getRowCount 缺失與錯誤
if (typeof p5 !== 'undefined' && p5.Table) {
    if (!p5.Table.prototype.getRowCount) { p5.Table.prototype.getRowCount = function() { return 0; }; }
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (!this || this.width === 0 || this.height === 0) {
            return [0,0,0,255];
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return [0,0,0,255];
        }
    };
}

